export const WORLD_OBJECTS=[['seed','egg','apple'],['acorn','block','leaf'],['shell','fish','egg'],['star','crystal','block']];
export function objectGroup(count,key='seed',{removed=0,group=0}={}){const o=OBJECTS[key]||OBJECTS.seed;return `<div class="object-group" role="group" aria-label="${count} ${o.many}${removed?', '+removed+' taken away':''}">${Array.from({length:count},(_,i)=>`<button class="math-object ${i>=count-removed?'taken-away':''}" data-object="${group}-${i}" aria-label="${o.one} ${i+1}" aria-pressed="false" ${i>=count-removed?'disabled':''}>${o.art}<span class="object-count" aria-hidden="true">${i+1}</span></button>`).join('')}</div>`;}
